:root {
  --bg-900: #0d1b2a;
  --bg-800: #1b2838;
  --bg-700: #22364d;
  --surface: #132436;
  --surface-2: #1a2f45;
  --text-100: #f2f8ff;
  --text-300: #b8c9dc;
  --text-500: #8aa3bd;
  --accent: #00b4d8;
  --accent-2: #0077b6;
  --success: #22c55e;
  --danger: #ef4444;
  --border: rgba(255, 255, 255, 0.12);
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  --radius: 14px;
  --container: 1180px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, "Segoe UI", Roboto, Arial, sans-serif;
  color: var(--text-100);
  background: radial-gradient(1300px 900px at 90% -10%, #204363 0%, var(--bg-900) 45%), var(--bg-900);
  line-height: 1.55;
}
a { color: inherit; text-decoration: none; }
.container { width: min(var(--container), 92%); margin: 0 auto; }
.header {
  position: sticky; top: 0; z-index: 40;
  backdrop-filter: blur(10px);
  background: rgba(13, 27, 42, 0.82);
  border-bottom: 1px solid var(--border);
}
.nav { display: flex; align-items: center; justify-content: space-between; height: 76px; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; letter-spacing: 0.2px; }
.logo-dot { width: 12px; height: 12px; border-radius: 50%; background: linear-gradient(120deg, var(--accent), #6ee7ff); box-shadow: 0 0 20px var(--accent); }
.menu { display: flex; align-items: center; gap: 22px; color: var(--text-300); }
.menu a:hover { color: var(--text-100); }
.dropdown { position: relative; }
.dropdown-menu {
  position: absolute; top: 32px; left: 0; min-width: 190px;
  background: var(--surface); border: 1px solid var(--border); border-radius: 10px;
  box-shadow: var(--shadow); display: none; padding: 8px;
}
.dropdown:hover .dropdown-menu, .dropdown:focus-within .dropdown-menu { display: block; }
.dropdown-menu a { display: block; padding: 9px 10px; border-radius: 8px; }
.dropdown-menu a:hover { background: var(--surface-2); }
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid transparent; border-radius: 10px; padding: 11px 16px;
  font-weight: 600; cursor: pointer; transition: 0.2s ease;
}
.btn-primary { background: linear-gradient(120deg, var(--accent), var(--accent-2)); color: white; }
.btn-primary:hover { transform: translateY(-1px); filter: brightness(1.05); }
.btn-ghost { border-color: var(--border); color: var(--text-300); }
.btn-ghost:hover { border-color: var(--accent); color: var(--text-100); }
.hero { padding: 78px 0 56px; }
.hero-grid { display: grid; grid-template-columns: 1.25fr 1fr; gap: 30px; align-items: center; }
.eyebrow { color: var(--accent); font-weight: 700; font-size: 0.86rem; text-transform: uppercase; letter-spacing: 1.2px; }
h1, h2, h3, h4 { line-height: 1.2; margin: 0 0 12px; }
h1 { font-size: clamp(2rem, 4.8vw, 3.5rem); }
h2 { font-size: clamp(1.55rem, 3.3vw, 2.35rem); }
h3 { font-size: 1.15rem; }
.lead { color: var(--text-300); max-width: 65ch; }
.card {
  background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}
.hero-card { padding: 22px; }
.section { padding: 62px 0; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
.grid-6 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.use-case { padding: 20px; min-height: 145px; }
.use-case h3 { margin-bottom: 8px; }
.muted { color: var(--text-300); }
.tabs { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 16px; }
.tab-btn {
  padding: 10px 14px; border-radius: 999px; border: 1px solid var(--border);
  background: transparent; color: var(--text-300); cursor: pointer;
}
.tab-btn.active { background: rgba(0, 180, 216, 0.14); border-color: var(--accent); color: var(--text-100); }
.tab-panel { display: none; }
.tab-panel.active { display: block; }
.diagram { padding: 20px; overflow: hidden; }
.ecosystem {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; align-items: center;
}
.node {
  padding: 14px; border: 1px solid var(--border); border-radius: 12px; background: var(--surface);
  text-align: center;
}
.node.core { background: linear-gradient(130deg, rgba(0,180,216,.2), rgba(0,119,182,.3)); border-color: rgba(0,180,216,.5); font-weight: 700; }
.connector { height: 2px; background: linear-gradient(90deg, transparent, var(--accent), transparent); margin: 6px 0; }
.accordion-item { border-top: 1px solid var(--border); }
.accordion-btn {
  width: 100%; text-align: left; border: 0; background: transparent; color: var(--text-100);
  padding: 16px 0; font-size: 1.02rem; font-weight: 600; cursor: pointer;
}
.accordion-content { display: none; color: var(--text-300); padding-bottom: 14px; }
.accordion-item.active .accordion-content { display: block; }
.stat-circles { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.circle {
  position: relative; width: 165px; height: 165px; margin: 0 auto; border-radius: 50%;
  background: conic-gradient(var(--accent) var(--pct), rgba(255,255,255,0.08) 0);
  display: grid; place-items: center;
}
.circle::after {
  content: ""; position: absolute; inset: 14px; border-radius: 50%; background: var(--bg-800);
  border: 1px solid var(--border);
}
.circle > div { position: relative; z-index: 2; text-align: center; }
.circle b { display: block; font-size: 1.35rem; }
.timeline-item { margin: 16px 0; }
.bar { height: 10px; border-radius: 999px; background: rgba(255,255,255,0.1); overflow: hidden; }
.bar > span { display: block; height: 100%; background: linear-gradient(90deg, var(--accent), var(--accent-2)); }
.carousel { overflow: hidden; }
.carousel-track { display: flex; transition: transform 0.4s ease; }
.quote { min-width: 100%; padding: 20px; }
.dots { display: flex; gap: 8px; justify-content: center; margin-top: 12px; }
.dot { width: 10px; height: 10px; border-radius: 50%; background: rgba(255,255,255,0.3); border: 0; cursor: pointer; }
.dot.active { background: var(--accent); }
.form { padding: 24px; }
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }
label { display: block; font-size: 0.9rem; color: var(--text-300); margin-bottom: 5px; }
input, select, textarea {
  width: 100%; padding: 10px 12px; border-radius: 10px; border: 1px solid var(--border);
  background: #11253a; color: var(--text-100);
}
input:focus, select:focus, textarea:focus { outline: 2px solid rgba(0,180,216,.45); border-color: var(--accent); }
.error { color: #ff8585; font-size: 0.82rem; min-height: 1em; }
.success-msg { color: #86efac; margin-top: 10px; }
.footer { border-top: 1px solid var(--border); padding: 28px 0; color: var(--text-500); margin-top: 40px; }
.cookie {
  position: fixed; bottom: 16px; left: 50%; transform: translateX(-50%);
  width: min(900px, 92%); background: var(--surface); border: 1px solid var(--border);
  border-radius: 12px; padding: 14px; display: none; z-index: 80;
}
.cookie.show { display: flex; gap: 14px; align-items: center; justify-content: space-between; }
.mobile-toggle { display: none; }
@media (max-width: 980px) {
  .hero-grid, .grid-3, .grid-2, .grid-6, .stat-circles { grid-template-columns: 1fr 1fr; }
  .menu { gap: 14px; }
}
@media (max-width: 760px) {
  .hero-grid, .grid-3, .grid-2, .grid-6, .stat-circles, .form-grid { grid-template-columns: 1fr; }
  .menu { display: none; position: absolute; top: 76px; left: 0; right: 0; background: var(--bg-900); padding: 16px; border-bottom: 1px solid var(--border); }
  .menu.show { display: grid; gap: 12px; }
  .mobile-toggle { display: inline-flex; }
}
EOF

cat > /app/output/main.js <<'EOF'
(function () {
  const q = (s, root = document) => root.querySelector(s);
  const qa = (s, root = document) => Array.from(root.querySelectorAll(s));

  qa('[data-tabs]').forEach((tabRoot) => {
    const buttons = qa('[role="tab"]', tabRoot);
    const panels = qa('[role="tabpanel"]', tabRoot);
    buttons.forEach((btn) => {
      btn.addEventListener('click', () => {
        const target = btn.getAttribute('data-target');
        buttons.forEach((b) => b.classList.remove('active'));
        panels.forEach((p) => p.classList.remove('active'));
        btn.classList.add('active');
        q(`#${target}`, tabRoot)?.classList.add('active');
      });
    });
  });

  qa('[data-accordion]').forEach((acc) => {
    qa('.accordion-btn', acc).forEach((btn) => {
      btn.addEventListener('click', () => {
        qa('.accordion-item', acc).forEach((item) => item.classList.remove('active'));
        btn.closest('.accordion-item')?.classList.add('active');
      });
    });
  });

  qa('[data-carousel]').forEach((root) => {
    const track = q('.carousel-track', root);
    const dots = qa('.dot', root);
    dots.forEach((dot, idx) => {
      dot.addEventListener('click', () => {
        track.style.transform = `translateX(-${idx * 100}%)`;
        dots.forEach((d) => d.classList.remove('active'));
        dot.classList.add('active');
      });
    });
  });

  const cookie = q('#cookieBanner');
  if (cookie) {
    const saved = localStorage.getItem('wellstream_cookie_pref');
    if (!saved) cookie.classList.add('show');
    q('#cookieAccept')?.addEventListener('click', () => {
      localStorage.setItem('wellstream_cookie_pref', 'accepted');
      cookie.classList.remove('show');
    });
    q('#cookieDecline')?.addEventListener('click', () => {
      localStorage.setItem('wellstream_cookie_pref', 'declined');
      cookie.classList.remove('show');
    });
  }

  const form = q('#demoForm');
  if (form) {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      let ok = true;
      qa('[data-required="true"]', form).forEach((field) => {
        const errorEl = q(`.error[data-for="${field.name}"]`, form);
        if (!field.value.trim()) {
          ok = false;
          if (errorEl) errorEl.textContent = 'This field is required.';
        } else {
          if (errorEl) errorEl.textContent = '';
        }
      });
      const email = q('input[name="email"]', form);
      const emailErr = q('.error[data-for="email"]', form);
      if (email && !/^\S+@\S+\.\S+$/.test(email.value)) {
        ok = false;
        if (emailErr) emailErr.textContent = 'Enter a valid email address.';
      }
      if (!ok) return;
      const success = q('#formSuccess');
      if (success) {
        success.textContent = 'Thank you. Your demo request has been submitted.';
      }
      form.reset();
    });
  }

  const toggle = q('#mobileMenuToggle');
  const menu = q('#mainMenu');
  toggle?.addEventListener('click', () => menu?.classList.toggle('show'));
})();
EOF

